import re

def parse_duration(text):
    if not isinstance(text, str) or not text.strip():
        return None

    text = text.strip()

    # Plain digits mean seconds
    if text.isdigit():
        return int(text)

    # Match optional hours, minutes, seconds in order
    match = re.match(r'^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$', text)
    if not match:
        return None

    h, m, s = match.groups()
    if h is None and m is None and s is None:
        return None

    total = 0
    if h is not None:
        total += int(h) * 3600
    if m is not None:
        total += int(m) * 60
    if s is not None:
        total += int(s)

    return total
